package com.aicharacter.v3;
/** Shared gravity/contact/traction model. Intent requests motion; physics determines realized motion. */
public final class WholeBodyPhysicsEngine{private WholeBodyPhysicsEngine(){}public static final double GRAVITY=9.81;
 public static void prepare(WorldState s,String actor,double dt){if(s==null||dt<=0)return;PhysicsBodyState p="cat".equals(actor)?s.catPhysics:s.girlPhysics;if(p==null)return;double wet=Math.max(0,Math.min(1,s.worldWetness));p.traction=Math.max(.28,1-wet*.38-("RAIN".equals(s.environment.weather)?s.environment.weatherIntensity*.12:0));double capability="cat".equals(actor)?catCapability(s):BodyInstinctEngine.movementCapacity(s);p.balance=Math.max(.15,Math.min(1,capability*(.72+.28*p.traction)));if(p.grounded){p.velocityY=0;p.groundReaction=p.massKg*GRAVITY;}else{p.velocityY+=GRAVITY*dt;p.groundReaction=0;}p.lastUpdatedAt=Math.max(p.lastUpdatedAt,System.currentTimeMillis());}
 public static double realizeHorizontalSpeed(WorldState s,String actor,double requested,double dt){PhysicsBodyState p="cat".equals(actor)?s.catPhysics:s.girlPhysics;if(p==null)return requested;prepare(s,actor,dt);double cap="cat".equals(actor)?catCapability(s):BodyInstinctEngine.movementCapacity(s);double target=requested*cap*p.traction*p.balance;double accel=(p.grounded?5.2:1.1)*Math.max(.25,p.traction);double maxDelta=accel*dt*requested;p.velocityX=approach(p.velocityX,target,maxDelta);return Math.max(0,Math.min(requested,Math.abs(p.velocityX)));}
 private static double catCapability(WorldState s){if(s.catState==null)return 1;double fatigue=Math.max(s.catState.sleepiness/100.0,Math.max(0,(30-s.catState.energy)/30.0));return Math.max(.45,1-fatigue*.42);}
 private static double approach(double v,double t,double d){if(v<t)return Math.min(t,v+d);return Math.max(t,v-d);}
}